/* Auth gate — only meaningful for the manual webhook input (schedule items carry no headers). */
const input = $input.first().json;
if (input.headers) {
  const provided = String(input.headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
  if (provided !== $env.CHAT_API_KEY) { return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }]; }
}
return [{ json: { ok: true } }];

/* Weekly review: gather week (todos/reminders/chats/memories/briefs), compose, save + push. */
const { Client } = require('pg');
let body = {};
try { body = $('Webhook Weekly').first().json.body || {}; } catch (e) {}
const dry = body && body.dry === true;
const scope = String(body.scope || 'owner').toLowerCase() === 'team' ? 'team' : 'owner';
const N8N = 'http://localhost:5678/api/v1';
const TG_URL = 'https://api.telegram.org/bot' + ($env.TELEGRAM_BOT_TOKEN || '') + '/sendMessage';
const apiJson = (method, path, qs, bodyB) => this.helpers.httpRequest({ method, url: N8N + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body: bodyB });

/* week window: Monday start, Asia/Shanghai */
const nowMs = Date.now();
const sh = new Date(nowMs + 8 * 3600 * 1000);
const dow = sh.getUTCDay();
const sinceMon = (dow + 6) % 7;
const monD = new Date(Date.UTC(sh.getUTCFullYear(), sh.getUTCMonth(), sh.getUTCDate() - sinceMon));
const weekStart = monD.toISOString().slice(0, 10);
const weekEnd = new Date(monD.getTime() + 6 * 86400000).toISOString().slice(0, 10);
const startMs = monD.getTime() - 8 * 3600 * 1000;
const inWeek = (t) => { const ms = Date.parse(t); return !isNaN(ms) && ms >= startMs && ms <= nowMs; };
const isSunday = sh.getUTCDay() === 0;
const forced = body.force === true || dry;
if (!isSunday && !forced) return [{ json: { ok: true, skipped: 'not-sunday', dow: sh.getUTCDay() } }];

const tables = (await apiJson('GET', '/data-tables', { limit: 100 })).data || [];
const tId = (name) => (tables.find((t) => t.name === name) || {}).id;
const rowsOf = async (name) => { const id = tId(name); if (!id) return []; return ((await apiJson('GET', '/data-tables/' + id + '/rows', { limit: 250 })).data || []); };
const todos = await rowsOf('todos');
const reminders = await rowsOf('reminders');
const briefs = await rowsOf('daily_briefs');
const people = await rowsOf('people');
const activePeople = people.filter((p) => p.active === 1 || p.active === true);
const nameOf = (ref) => { if (!ref) return ''; const p = people.find((x) => x.name === ref); return p ? (p.display_name || p.name) : ref; };
let exTotal = 0, exTg = 0;
const exDays = [0, 0, 0, 0, 0, 0, 0];
try {
  const ec = new Client({ host: $env.DB_POSTGRESDB_HOST || 'postgres', port: Number($env.DB_POSTGRESDB_PORT || 5432), database: $env.DB_POSTGRESDB_DATABASE || 'n8n', user: $env.DB_POSTGRESDB_USER || 'n8n', password: $env.DB_POSTGRESDB_PASSWORD });
  await ec.connect();
  const q1 = await ec.query('SELECT count(DISTINCT execution_id)::int AS total, count(DISTINCT execution_id) FILTER (WHERE client = $2)::int AS tg FROM "data_table_user_rS98dlI0DJWv2WK9" WHERE "createdAt" >= $1 AND (client = $2 OR client = $4 OR session_id LIKE $3)', [new Date(startMs).toISOString(), 'telegram', 'user\_%', 'stream-bridge']);
  exTotal = (q1.rows[0] && q1.rows[0].total) || 0;
  exTg = (q1.rows[0] && q1.rows[0].tg) || 0;
  const q2 = await ec.query('SELECT EXTRACT(ISODOW FROM ("createdAt" + make_interval(hours => 8)))::int AS d, count(DISTINCT execution_id)::int AS n FROM "data_table_user_rS98dlI0DJWv2WK9" WHERE "createdAt" >= $1 AND (client = $2 OR client = $4 OR session_id LIKE $3) GROUP BY d', [new Date(startMs).toISOString(), 'telegram', 'user\_%', 'stream-bridge']);
  for (const row of q2.rows) { exDays[(row.d + 6) % 7] = row.n; }
  await ec.end();
} catch (e) {}

const today = sh.toISOString().slice(0, 10);
const doneTodos = todos.filter((r) => r.status === 'done' && inWeek(r.completed_at));
const openTodos = todos.filter((r) => r.status === 'open');
const sentRem = reminders.filter((r) => r.status === 'sent' && inWeek(r.due_at));
const pendRem = reminders.filter((r) => r.status === 'pending' && Date.parse(r.due_at) > nowMs);
const briefsWk = briefs.filter((r) => inWeek(r.createdAt)).sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt));

let mems = [];
try {
  const c = new Client({ host: $env.DB_POSTGRESDB_HOST || 'postgres', port: Number($env.DB_POSTGRESDB_PORT || 5432), database: $env.DB_POSTGRESDB_DATABASE || 'n8n', user: $env.DB_POSTGRESDB_USER || 'n8n', password: $env.DB_POSTGRESDB_PASSWORD });
  await c.connect();
  const m = await c.query('SELECT text FROM agent_memories WHERE created_at >= $1 ORDER BY created_at DESC LIMIT 5', [new Date(startMs).toISOString()]);
  mems = m.rows.map((r) => r.text);
  await c.end();
} catch (e) {}

const dayNames = ['一', '二', '三', '四', '五', '六', '日'];
let topIdx = 0; for (let i = 1; i < 7; i++) if (exDays[i] > exDays[topIdx]) topIdx = i;

const L = [];
L.push('🗓️ 本周回顾' + (scope === 'team' ? '（团队）' : '') + ' · ' + weekStart + ' ~ ' + weekEnd + '（更新至 ' + today + '）');
L.push('');
L.push('【待办】完成 ' + doneTodos.length + ' · 开放 ' + openTodos.length);
doneTodos.slice(0, 6).forEach((r) => L.push('✅ ' + r.text));
openTodos.slice(0, 8).forEach((r) => L.push('🔵 ' + r.text + (r.due_date ? '（' + r.due_date + (r.due_date < today ? ' · 已逾期' : '') + '）' : '')));
if (!doneTodos.length && !openTodos.length) L.push('（本周暂无待办）');
if (scope === 'team') {
  const assignedOpen = openTodos.filter((r) => (r.owner_ref || ''));
  const unassigned = openTodos.filter((r) => !(r.owner_ref || ''));
  L.push('');
  L.push('【团队】' + activePeople.length + ' 人 · 已指派开放 ' + assignedOpen.length + ' 项 · 未指派 ' + unassigned.length + ' 项');
  const plines = activePeople.map((p) => {
    const mine = openTodos.filter((r) => (r.owner_ref || '') === p.name);
    const over = mine.filter((r) => r.due_date && r.due_date < today).length;
    const doneN = doneTodos.filter((r) => (r.owner_ref || '') === p.name).length;
    const ackN = mine.filter((r) => r.ack_at).length;
    const escN = mine.filter((r) => Number(r.escalated || 0) === 1).length;
    return '• ' + (p.display_name || p.name) + '：开放 ' + mine.length + (over ? '（逾期 ' + over + '）' : '') + ' · 本周完成 ' + doneN + (ackN ? ' · 已确认 ' + ackN : '') + (escN ? ' · 升级 ' + escN : '');
  });
  if (!activePeople.length) plines.push('（人员目录为空 —— 先在控制台 People 页录入）');
  plines.forEach((x) => L.push(x));
  const detail = assignedOpen.slice(0, 6).map((r) => '  ↳ ' + nameOf(r.owner_ref) + '：' + r.text + (r.due_date ? '（' + r.due_date + (r.due_date < today ? ' · 逾期' : '') + '）' : ''));
  if (detail.length) { L.push('未完成明细：'); detail.forEach((x) => L.push(x)); }
}
L.push('');
L.push('【提醒】触发 ' + sentRem.length + ' 条 · 待触发 ' + pendRem.length + ' 条');
pendRem.slice(0, 4).forEach((r) => L.push('⏳ ' + String(r.text).slice(0, 40) + '（' + String(r.due_at).slice(5, 16).replace('T', ' ') + '）'));
L.push('');
L.push('【对话】' + exTotal + ' 轮（TG ' + exTg + ' · 其它 ' + (exTotal - exTg) + '）' + (exTotal ? ' · 最活跃：周' + dayNames[topIdx] : ''));
if (mems.length) { L.push(''); L.push('【新记忆】' + mems.length + ' 条'); mems.slice(0, 3).forEach((t) => L.push('🧠 ' + String(t).slice(0, 60))); }
L.push('');
L.push('【晨报】本周 ' + briefsWk.length + ' 份' + (briefsWk.length ? '（最新：' + briefsWk[0].title + '）' : ''));

let insight = '';
try {
  const stats = '本周待办完成' + doneTodos.length + '项、开放' + openTodos.length + '项；提醒触发' + sentRem.length + '条；对话' + exTotal + '轮；新记忆' + mems.length + '条。' + (scope === 'team' ? '团队共' + activePeople.length + '人，已指派开放' + openTodos.filter((r) => (r.owner_ref || '')).length + '项。' : '');
  const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.deepseek.com/chat/completions', headers: { Authorization: ['Bea', 'rer '].join('') + ($env.UPSTREAM_API_KEY || ''), 'Content-Type': 'application/json' }, body: { model: 'deepseek-v4-flash', messages: [{ role: 'system', content: '你给主人的周报写一句总结。不超过55字，自然、具体、像朋友说话，可带一个轻建议。只输出这一句话。' }, { role: 'user', content: stats }], stream: false, temperature: 0.6, max_tokens: 1200 }, timeout: 45000 });
  insight = String((r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '').trim().replace(new RegExp('^[\"「]|[\"」]$', 'g'), '').slice(0, 100);
} catch (e) {}
if (insight) { L.push(''); L.push('—— ' + insight); }
const content = L.join(String.fromCharCode(10));

let saved = false;
let pushed = false;
if (!dry) {
  try {
    let wid = tId('weekly_reviews');
    if (!wid) {
      const t = await apiJson('POST', '/data-tables', null, { name: 'weekly_reviews', columns: [{ name: 'week_start', type: 'string' }, { name: 'week_end', type: 'string' }, { name: 'content_md', type: 'string' }, { name: 'stats_json', type: 'string' }] });
      wid = t && t.id;
    }
    if (wid) {
      await apiJson('POST', '/data-tables/' + wid + '/rows', null, { data: [{ week_start: weekStart, week_end: weekEnd, content_md: content, scope, people_count: activePeople.length, stats_json: JSON.stringify({ scope, people: activePeople.length, done: doneTodos.length, open: openTodos.length, assigned: openTodos.filter((r) => (r.owner_ref || '')).length, sent: sentRem.length, pending: pendRem.length, execs: exTotal, mems: mems.length }) }] });
      saved = true;
    }
  } catch (e) {}
  try {
    const t = await this.helpers.httpRequest({ method: 'POST', url: TG_URL, headers: { 'Content-Type': 'application/json' }, body: { chat_id: $env.TELEGRAM_CHAT_ID, text: content.slice(0, 3800) }, timeout: 30000 });
    pushed = !!(t && t.ok);
  } catch (e) {}
}
return [{ json: { ok: true, dry, scope, people_count: activePeople.length, saved, pushed, chars: content.length, todo_done: doneTodos.length, todo_open: openTodos.length, rem_sent: sentRem.length, rem_pending: pendRem.length, execs: exTotal, mems: mems.length, content } }];

/* Slots Sun 09:00 / 14:00 / 20:00. Same reason as the others: a desktop host is often off at the original 20:00, and a weekly job that misses its slot is silent for seven days. Once one slot has landed this ISO week the rest must be no-ops. */
const N8N = 'http://localhost:5678/api/v1';
const H = { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' };
const api = (m, p, qs, b) => this.helpers.httpRequest({ method: m, url: N8N + p, headers: H, qs, body: b, timeout: 15000 });
/* 失败要 fail-open：守卫查不到状态时宁可多跑一次，也不能把任务悄悄掐死。 */
const table = async () => {
  try {
    let t = (((await api('GET', '/data-tables', { limit: 100 })).data) || []).find((x) => x.name === 'cron_runs');
    if (!t || !t.id) {
      t = await api('POST', '/data-tables', null, { name: 'cron_runs', columns: [
        { name: 'job', type: 'string' }, { name: 'period', type: 'string' },
        { name: 'ran_at', type: 'string' }, { name: 'source', type: 'string' } ] });
    }
    return (t && t.id) ? t : null;
  } catch (e) { return null; }
};
/* once per ISO week, not once per day */
const _d = new Date(new Date().getTime() - new Date().getTimezoneOffset() * 60000);
const _t = new Date(Date.UTC(_d.getUTCFullYear(), _d.getUTCMonth(), _d.getUTCDate()));
const _day = _t.getUTCDay() || 7;
_t.setUTCDate(_t.getUTCDate() + 4 - _day);
const _ys = new Date(Date.UTC(_t.getUTCFullYear(), 0, 1));
const _w = Math.ceil((((_t - _ys) / 86400000) + 1) / 7);
const period = _t.getUTCFullYear() + '-W' + String(_w).padStart(2, '0');
let t = await table();
if (!t) return $input.all();
let rows = [];
try { rows = (((await api('GET', '/data-tables/' + t.id + '/rows', { limit: 250 })).data) || []); } catch (e2) { return $input.all(); }
if (rows.some((r) => r.job === 'weekly_review' && String(r.period || '') === period)) return [];
return $input.all();

/* Record that this period is done, so the remaining schedule slots no-op.
   Runs only after the work succeeded: if the run throws, n8n stops here and the
   marker is never written, so a later slot still gets its chance. */
const N8N = 'http://localhost:5678/api/v1';
const H = { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' };
const api = (m, p, qs, b) => this.helpers.httpRequest({ method: m, url: N8N + p, headers: H, qs, body: b, timeout: 15000 });
/* 失败要 fail-open：守卫查不到状态时宁可多跑一次，也不能把任务悄悄掐死。 */
const table = async () => {
  try {
    let t = (((await api('GET', '/data-tables', { limit: 100 })).data) || []).find((x) => x.name === 'cron_runs');
    if (!t || !t.id) {
      t = await api('POST', '/data-tables', null, { name: 'cron_runs', columns: [
        { name: 'job', type: 'string' }, { name: 'period', type: 'string' },
        { name: 'ran_at', type: 'string' }, { name: 'source', type: 'string' } ] });
    }
    return (t && t.id) ? t : null;
  } catch (e) { return null; }
};
/* once per ISO week, not once per day */
const _d = new Date(new Date().getTime() - new Date().getTimezoneOffset() * 60000);
const _t = new Date(Date.UTC(_d.getUTCFullYear(), _d.getUTCMonth(), _d.getUTCDate()));
const _day = _t.getUTCDay() || 7;
_t.setUTCDate(_t.getUTCDate() + 4 - _day);
const _ys = new Date(Date.UTC(_t.getUTCFullYear(), 0, 1));
const _w = Math.ceil((((_t - _ys) / 86400000) + 1) / 7);
const period = _t.getUTCFullYear() + '-W' + String(_w).padStart(2, '0');
let source = 'schedule';
try { if ($('Webhook Weekly').first().json) source = 'manual'; } catch (e) {}
try {
  const t = await table();
  if (t) await api('POST', '/data-tables/' + t.id + '/rows', null, { data: [{
    job: 'weekly_review', period, ran_at: new Date().toISOString(), source }] });
} catch (e3) {}
return $input.all();
